<script lang="ts">
 import {dialogFocus} from './lib/dialog';
 import {importAvailability,importData} from './lib/api';
 let {version,firstRun=false,refresh}:{version:string;firstRun?:boolean;refresh:()=>void}=$props();
 let empty=$state(false),legacy=$state(false),show=$state(false),busy=$state(false),result=$state<{title:string;message:string}|null>(null);
 $effect(()=>{void version;void importAvailability().then(([e,l])=>{empty=e;legacy=l;}).catch(e=>{result={title:'No se pudo importar',message:String(e)};});});
 async function run(source:string){if(busy)return;busy=true;try{const s=await importData(source);if(s){result={title:'Importación completa',message:`${s.accounts} cuentas, ${s.categories} categorías, ${s.payees} comercios, ${s.entries} movimientos y ${s.schedules} pagos programados.`};show=false;refresh();}}catch(e){const message=String(e);result=message.includes('Ya tienes datos')?{title:'Ya tienes datos',message:'La importación solo funciona en una base vacía para no duplicar movimientos.'}:{title:'No se pudo importar',message};}finally{busy=false;}}
</script>
{#if firstRun && empty}<section class="banner"><h2>Importar datos</h2>{#if legacy}<button disabled={busy} onclick={()=>run('legacy')}>Importar mis datos de la app anterior</button>{/if}<button disabled={busy} onclick={()=>run('actual')}>Importar desde Actual…</button></section>{:else if !firstRun}<button onclick={()=>show=!show}>Importar…</button>{#if show}<div class="choices">{#if legacy}<button disabled={busy} onclick={()=>run('legacy')}>Importar mis datos de la app anterior</button>{/if}<button disabled={busy} onclick={()=>run('actual')}>Importar desde Actual…</button></div>{/if}{/if}
{#if result}<div class="backdrop"><div class="modal" use:dialogFocus role="alertdialog" aria-modal="true" aria-labelledby="import-title" aria-describedby="import-message" tabindex="-1" onkeydown={e=>{if(e.key==='Escape')result=null;}}><h2 id="import-title">{result.title}</h2><p id="import-message">{result.message}</p><button onclick={()=>result=null}>Aceptar</button></div></div>{/if}
<style>.banner{background:var(--card);border:1px solid var(--border);border-radius:18px;padding:20px}h2{font-size:1rem;margin:0 0 12px}button{font:inherit;background:var(--canvas);color:inherit;border:1px solid var(--border);border-radius:8px;padding:8px;margin-right:8px;cursor:pointer}.choices{margin-top:10px}.backdrop{position:fixed;inset:0;background:#0009;display:grid;place-items:center;z-index:20}.modal{background:var(--card);padding:24px;border-radius:16px;max-width:450px}</style>
